import { useState, useRef, useCallback } from 'react';
import {
  Upload, X, FileText, Settings, Loader2, Sparkles,
  Check, Calendar, User, Briefcase
} from 'lucide-react';

interface UploadedFile {
  id: string;
  name: string;
  size: number;
  type: string;
  content_base64: string;
}

interface CandidateUploadProps {
  onUpload?: (data: UploadPayload) => void;
  isProcessing?: boolean;
}

export interface UploadPayload {
  action: 'process_candidates';
  files: { name: string; content_base64: string }[];
  transcripts: Record<string, string>;
  communicate_time: string;
  channel: string;
  intern_name: string;
}

const MAX_FILE_SIZE = 5 * 1024 * 1024; // 5MB per file
const MAX_TOTAL_SIZE = 20 * 1024 * 1024; // 20MB total

export function CandidateUpload({ onUpload, isProcessing }: CandidateUploadProps) {
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [transcripts, setTranscripts] = useState<Record<string, string>>({});
  const [communicateTime, setCommunicateTime] = useState(() => {
    const today = new Date();
    return today.toISOString().split('T')[0];
  });
  const [channel, setChannel] = useState('BOSS直聘');
  const [internName, setInternName] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const processFile = (file: File): Promise<UploadedFile> => {
    return new Promise((resolve, reject) => {
      if (file.size > MAX_FILE_SIZE) {
        reject(new Error(`文件 ${file.name} 超过 5MB 限制`));
        return;
      }
      const reader = new FileReader();
      reader.onload = () => {
        const base64 = (reader.result as string).split(',')[1];
        resolve({
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          size: file.size,
          type: file.type,
          content_base64: base64,
        });
      };
      reader.onerror = () => reject(new Error(`读取 ${file.name} 失败`));
      reader.readAsDataURL(file);
    });
  };

  const addFiles = useCallback(async (newFiles: FileList | null) => {
    if (!newFiles || newFiles.length === 0) return;
    setError(null);

    const validFiles = Array.from(newFiles).filter(
      (f) => f.type === 'application/pdf' || f.name.endsWith('.pdf')
    );

    if (validFiles.length === 0) {
      setError('请上传 PDF 格式的简历文件');
      return;
    }

    const currentTotal = files.reduce((sum, f) => sum + f.size, 0);
    const newTotal = validFiles.reduce((sum, f) => sum + f.size, 0);
    if (currentTotal + newTotal > MAX_TOTAL_SIZE) {
      setError('总文件大小超过 20MB 限制');
      return;
    }

    try {
      const uploaded = await Promise.all(validFiles.map(processFile));
      setFiles((prev) => [...prev, ...uploaded]);
      // Initialize transcripts for new files
      setTranscripts((prev) => {
        const next = { ...prev };
        uploaded.forEach((f) => {
          const key = f.name.replace(/\.pdf$/i, '');
          if (!(key in next)) next[key] = '';
        });
        return next;
      });
    } catch (err: any) {
      setError(err.message);
    }
  }, [files]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    addFiles(e.dataTransfer.files);
  }, [addFiles]);

  const handleFileSelect = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    addFiles(e.target.files);
    e.target.value = ''; // Reset input
  }, [addFiles]);

  const removeFile = useCallback((id: string) => {
    setFiles((prev) => prev.filter((f) => f.id !== id));
  }, []);

  const handleProcess = useCallback(() => {
    if (files.length === 0) {
      setError('请先上传至少一个简历文件');
      return;
    }
    setError(null);

    onUpload?.({
      action: 'process_candidates',
      files: files.map((f) => ({ name: f.name, content_base64: f.content_base64 })),
      transcripts,
      communicate_time: communicateTime,
      channel,
      intern_name: internName,
    });
  }, [files, transcripts, communicateTime, channel, internName, onUpload]);

  const formatSize = (bytes: number) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  return (
    <div className="w-full h-full overflow-auto" style={{ backgroundColor: 'var(--bg-base)' }}>
      <div className="p-6 md:p-8" style={{ maxWidth: '960px', margin: '0 auto' }}>
        {/* Page Title */}
        <h2
          className="mb-2"
          style={{
            fontSize: 'var(--text-2xl)',
            fontWeight: 'var(--font-semibold)',
            color: 'var(--text-primary)',
          }}
        >
          新增候选人
        </h2>
        <p
          className="mb-6"
          style={{
            fontSize: 'var(--text-base)',
            color: 'var(--text-secondary)',
          }}
        >
          上传简历 → 输入电话纪要 → AI 自动分析评分
        </p>

        {/* Upload Zone */}
        <div
          onClick={() => fileInputRef.current?.click()}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          className="mb-6 flex flex-col items-center justify-center cursor-pointer"
          style={{
            height: '200px',
            border: `1.5px dashed ${isDragging ? 'var(--accent)' : 'var(--border-strong)'}`,
            borderRadius: 'var(--radius-xl)',
            backgroundColor: isDragging ? 'var(--accent-light)' : 'transparent',
            boxShadow: isDragging ? 'var(--shadow-glow)' : 'none',
            transition: 'all var(--duration-normal) var(--ease-out)',
          }}
        >
          <Upload
            size={32}
            style={{ color: isDragging ? 'var(--accent)' : 'var(--text-muted)', marginBottom: 'var(--space-4)' }}
          />
          <p
            style={{
              fontSize: 'var(--text-md)',
              color: isDragging ? 'var(--accent)' : 'var(--text-secondary)',
              marginBottom: 'var(--space-2)',
              fontWeight: 'var(--font-medium)',
            }}
          >
            {isDragging ? '松开以上传文件' : '拖拽简历到此处，或点击上传'}
          </p>
          <p
            style={{
              fontSize: 'var(--text-sm)',
              color: 'var(--text-muted)',
            }}
          >
            支持 PDF 格式，单个文件不超过 5MB
          </p>
          <input
            ref={fileInputRef}
            type="file"
            multiple
            accept=".pdf"
            onChange={handleFileSelect}
            style={{ display: 'none' }}
          />
        </div>

        {/* Error Message */}
        {error && (
          <div
            className="mb-4 p-3 flex items-center gap-2"
            style={{
              backgroundColor: 'var(--danger-bg)',
              borderRadius: 'var(--radius-md)',
              color: 'var(--danger)',
              fontSize: 'var(--text-sm)',
            }}
          >
            <X size={16} />
            {error}
          </div>
        )}

        {/* File List */}
        {files.length > 0 && (
          <div
            className="mb-6"
            style={{
              backgroundColor: 'var(--bg-surface)',
              border: '1px solid var(--border-subtle)',
              borderRadius: 'var(--radius-lg)',
              overflow: 'hidden',
            }}
          >
            <div
              className="px-4 py-3 flex items-center justify-between"
              style={{
                borderBottom: '1px solid var(--border-subtle)',
                fontSize: 'var(--text-sm)',
                color: 'var(--text-secondary)',
                fontWeight: 'var(--font-medium)',
              }}
            >
              <span>已上传文件 ({files.length})</span>
              <span>{formatSize(files.reduce((s, f) => s + f.size, 0))}</span>
            </div>
            {files.map((file) => (
              <div
                key={file.id}
                className="flex items-center justify-between px-4"
                style={{
                  height: '52px',
                  borderBottom: '1px solid var(--border-subtle)',
                }}
              >
                <div className="flex items-center gap-3 min-w-0">
                  <FileText size={20} style={{ color: 'var(--accent)', flexShrink: 0 }} />
                  <span
                    className="truncate"
                    style={{
                      fontSize: 'var(--text-base)',
                      color: 'var(--text-primary)',
                    }}
                  >
                    {file.name}
                  </span>
                  <span
                    style={{
                      fontSize: 'var(--text-xs)',
                      color: 'var(--text-muted)',
                      flexShrink: 0,
                    }}
                  >
                    {formatSize(file.size)}
                  </span>
                </div>
                <button
                  onClick={() => removeFile(file.id)}
                  className="flex items-center justify-center transition-colors flex-shrink-0"
                  style={{
                    width: '32px',
                    height: '32px',
                    borderRadius: 'var(--radius-md)',
                    backgroundColor: 'transparent',
                    border: 'none',
                    cursor: 'pointer',
                    color: 'var(--text-secondary)',
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = 'var(--danger-bg)';
                    e.currentTarget.style.color = 'var(--danger)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = 'transparent';
                    e.currentTarget.style.color = 'var(--text-secondary)';
                  }}
                >
                  <X size={16} />
                </button>
              </div>
            ))}
          </div>
        )}

        {/* Phone Transcripts */}
        {files.length > 0 && (
          <div className="mb-6 space-y-4">
            <h3
              style={{
                fontSize: 'var(--text-lg)',
                fontWeight: 'var(--font-medium)',
                color: 'var(--text-primary)',
                marginBottom: 'var(--space-4)',
              }}
            >
              电话面试纪要
            </h3>
            {files.map((file) => {
              const key = file.name.replace(/\.pdf$/i, '');
              return (
                <div
                  key={file.id}
                  className="p-4"
                  style={{
                    backgroundColor: 'var(--bg-surface)',
                    border: '1px solid var(--border-subtle)',
                    borderRadius: 'var(--radius-lg)',
                  }}
                >
                  <div
                    className="flex items-center gap-2 mb-2"
                    style={{
                      fontSize: 'var(--text-sm)',
                      color: 'var(--text-secondary)',
                      fontWeight: 'var(--font-medium)',
                    }}
                  >
                    <User size={14} />
                    {key}
                  </div>
                  <textarea
                    placeholder="请粘贴该候选人的电话面试纪要内容..."
                    value={transcripts[key] || ''}
                    onChange={(e) =>
                      setTranscripts((prev) => ({ ...prev, [key]: e.target.value }))
                    }
                    style={{
                      width: '100%',
                      minHeight: '100px',
                      padding: 'var(--space-3)',
                      backgroundColor: 'var(--bg-input)',
                      border: '1px solid var(--border-subtle)',
                      borderRadius: 'var(--radius-md)',
                      color: 'var(--text-primary)',
                      fontSize: 'var(--text-base)',
                      lineHeight: 'var(--leading-relaxed)',
                      resize: 'vertical',
                      outline: 'none',
                      fontFamily: 'var(--font-sans)',
                    }}
                    onFocus={(e) => {
                      e.currentTarget.style.borderColor = 'var(--border-focus)';
                    }}
                    onBlur={(e) => {
                      e.currentTarget.style.borderColor = 'var(--border-subtle)';
                    }}
                  />
                </div>
              );
            })}
          </div>
        )}

        {/* Settings Panel */}
        <div
          className="mb-6 p-5"
          style={{
            backgroundColor: 'var(--bg-surface)',
            border: '1px solid var(--border-subtle)',
            borderRadius: 'var(--radius-lg)',
          }}
        >
          <div
            className="flex items-center gap-2 mb-4"
            style={{
              fontSize: 'var(--text-lg)',
              fontWeight: 'var(--font-medium)',
              color: 'var(--text-primary)',
            }}
          >
            <Settings size={18} style={{ color: 'var(--accent)' }} />
            处理设置
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label
                className="flex items-center gap-2 mb-2"
                style={{
                  fontSize: 'var(--text-sm)',
                  color: 'var(--text-muted)',
                }}
              >
                <Calendar size={14} />
                沟通日期
              </label>
              <input
                type="date"
                value={communicateTime}
                onChange={(e) => setCommunicateTime(e.target.value)}
                style={{
                  width: '100%',
                  height: '36px',
                  padding: '0 12px',
                  backgroundColor: 'var(--bg-input)',
                  border: '1px solid var(--border-subtle)',
                  borderRadius: 'var(--radius-md)',
                  color: 'var(--text-primary)',
                  fontSize: 'var(--text-base)',
                  outline: 'none',
                }}
                onFocus={(e) => {
                  e.currentTarget.style.borderColor = 'var(--border-focus)';
                }}
                onBlur={(e) => {
                  e.currentTarget.style.borderColor = 'var(--border-subtle)';
                }}
              />
            </div>

            <div>
              <label
                className="flex items-center gap-2 mb-2"
                style={{
                  fontSize: 'var(--text-sm)',
                  color: 'var(--text-muted)',
                }}
              >
                <Briefcase size={14} />
                招聘渠道
              </label>
              <select
                value={channel}
                onChange={(e) => setChannel(e.target.value)}
                style={{
                  width: '100%',
                  height: '36px',
                  padding: '0 12px',
                  backgroundColor: 'var(--bg-input)',
                  border: '1px solid var(--border-subtle)',
                  borderRadius: 'var(--radius-md)',
                  color: 'var(--text-primary)',
                  fontSize: 'var(--text-base)',
                  outline: 'none',
                  cursor: 'pointer',
                }}
                onFocus={(e) => {
                  e.currentTarget.style.borderColor = 'var(--border-focus)';
                }}
                onBlur={(e) => {
                  e.currentTarget.style.borderColor = 'var(--border-subtle)';
                }}
              >
                <option>BOSS直聘</option>
                <option>智联招聘</option>
                <option>前程无忧</option>
                <option>猎聘网</option>
                <option>内部推荐</option>
                <option>校园招聘</option>
                <option>其他</option>
              </select>
            </div>

            <div>
              <label
                className="flex items-center gap-2 mb-2"
                style={{
                  fontSize: 'var(--text-sm)',
                  color: 'var(--text-muted)',
                }}
              >
                <User size={14} />
                跟进实习生
              </label>
              <input
                type="text"
                placeholder="请输入实习生姓名"
                value={internName}
                onChange={(e) => setInternName(e.target.value)}
                style={{
                  width: '100%',
                  height: '36px',
                  padding: '0 12px',
                  backgroundColor: 'var(--bg-input)',
                  border: '1px solid var(--border-subtle)',
                  borderRadius: 'var(--radius-md)',
                  color: 'var(--text-primary)',
                  fontSize: 'var(--text-base)',
                  outline: 'none',
                }}
                onFocus={(e) => {
                  e.currentTarget.style.borderColor = 'var(--border-focus)';
                }}
                onBlur={(e) => {
                  e.currentTarget.style.borderColor = 'var(--border-subtle)';
                }}
              />
            </div>
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-3">
          <button
            onClick={handleProcess}
            disabled={files.length === 0 || isProcessing}
            className="flex items-center justify-center gap-2 transition-all"
            style={{
              height: '40px',
              padding: '0 24px',
              backgroundColor: files.length === 0 || isProcessing ? 'var(--bg-hover)' : 'var(--accent)',
              color: files.length === 0 || isProcessing ? 'var(--text-muted)' : 'var(--text-inverse)',
              fontSize: 'var(--text-base)',
              fontWeight: 'var(--font-medium)',
              borderRadius: 'var(--radius-md)',
              border: 'none',
              cursor: files.length === 0 || isProcessing ? 'not-allowed' : 'pointer',
              opacity: files.length === 0 || isProcessing ? 0.4 : 1,
            }}
            onMouseEnter={(e) => {
              if (files.length > 0 && !isProcessing) {
                e.currentTarget.style.backgroundColor = 'var(--accent-hover)';
                e.currentTarget.style.boxShadow = 'var(--shadow-glow)';
              }
            }}
            onMouseLeave={(e) => {
              if (files.length > 0 && !isProcessing) {
                e.currentTarget.style.backgroundColor = 'var(--accent)';
                e.currentTarget.style.boxShadow = 'none';
              }
            }}
          >
            {isProcessing ? (
              <>
                <Loader2 size={18} className="animate-spin" />
                分析处理中...
              </>
            ) : (
              <>
                <Sparkles size={18} />
                开始分析处理
              </>
            )}
          </button>

          {files.length > 0 && !isProcessing && (
            <button
              onClick={() => {
                setFiles([]);
                setTranscripts({});
                setError(null);
              }}
              className="transition-colors"
              style={{
                height: '40px',
                padding: '0 16px',
                backgroundColor: 'transparent',
                color: 'var(--text-secondary)',
                fontSize: 'var(--text-sm)',
                fontWeight: 'var(--font-medium)',
                borderRadius: 'var(--radius-md)',
                border: 'none',
                cursor: 'pointer',
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.color = 'var(--text-primary)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.color = 'var(--text-secondary)';
              }}
            >
              清空
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
