import React from 'react'
import ReactDOM from 'react-dom/client'
import { Streamlit, StreamlitComponentBase, withStreamlitConnection } from 'streamlit-component-lib'
import './theme.css'
import { CandidateBrowser } from './components/CandidateBrowser'
import { CandidateUpload, type UploadPayload } from './components/CandidateUpload'

interface State {
  numClicks: number
}

class ZhaopinComponent extends StreamlitComponentBase<State> {
  public state = { numClicks: 0 }

  public render = (): React.ReactNode => {
    const { args } = this.props
    const componentType = args.component as string
    const theme = (args.theme as 'neutral' | 'moss') || 'neutral'

    // Apply theme to document root
    if (typeof document !== 'undefined') {
      document.documentElement.setAttribute('data-theme', theme)
    }

    // Set Streamlit iframe height automatically
    Streamlit.setFrameHeight()

    if (componentType === 'candidate_browser') {
      return (
        <CandidateBrowser
          candidates={args.candidates || []}
          selectedId={args.selected_id}
          onSelect={(candidate: any) => {
            Streamlit.setComponentValue({ action: 'select', candidate_id: candidate.id })
          }}
          onEdit={(candidate: any) => {
            Streamlit.setComponentValue({ action: 'edit', candidate })
          }}
          onDelete={(candidateId: number) => {
            Streamlit.setComponentValue({ action: 'delete', candidate_id: candidateId })
          }}
          onReanalyze={(candidateId: number) => {
            Streamlit.setComponentValue({ action: 'reanalyze', candidate_id: candidateId })
          }}
          onExport={(candidateId: number) => {
            Streamlit.setComponentValue({ action: 'export', candidate_id: candidateId })
          }}
          onResultChange={(candidateId: number, result: string | null) => {
            Streamlit.setComponentValue({ action: 'result_change', candidate_id: candidateId, result })
          }}
        />
      )
    }

    if (componentType === 'candidate_upload') {
      return (
        <CandidateUpload
          isProcessing={args.is_processing || false}
          onUpload={(data: UploadPayload) => {
            Streamlit.setComponentValue(data)
          }}
        />
      )
    }

    return (
      <div style={{ padding: 24, color: 'var(--text-secondary)' }}>
        未知组件类型: {componentType}
      </div>
    )
  }
}

const WrappedComponent = withStreamlitConnection(ZhaopinComponent)

const rootElement = document.getElementById('root')
if (rootElement) {
  const root = ReactDOM.createRoot(rootElement)
  root.render(
    <React.StrictMode>
      <WrappedComponent />
    </React.StrictMode>
  )
}
