import { useState, useMemo, useCallback } from 'react';
import {
  Search, Copy, MoreHorizontal, Pencil, Trash2,
  Download, Sparkles, Star, Check, X, Loader2,
  ChevronLeft, Filter
} from 'lucide-react';

interface ScoreDetail {
  [dimension: string]: number;
}

export interface Candidate {
  id: number;
  name: string;
  phone: string;
  email?: string;
  gender?: string;
  birth_year?: number | null;
  school?: string;
  major?: string;
  education?: string;
  is_fresh_grad?: string;
  channel?: string;
  intern_name?: string;
  communicate_time?: string;
  description?: string;
  remarks?: string;
  result?: string | null;
  score_total?: number;
  score_details?: ScoreDetail;
  ai_score_details?: ScoreDetail;
  resume_raw_text?: string;
  score_source?: string;
}

interface CandidateBrowserProps {
  candidates: Candidate[];
  selectedId?: number | null;
  onSelect?: (candidate: Candidate) => void;
  onEdit?: (candidate: Candidate) => void;
  onDelete?: (candidateId: number) => void;
  onReanalyze?: (candidateId: number) => void;
  onExport?: (candidateId: number) => void;
  onResultChange?: (candidateId: number, result: string | null) => void;
}

const statusConfig: Record<string, { label: string; bg: string; color: string }> = {
  '推荐': { label: '推荐', bg: 'var(--success-bg)', color: 'var(--success)' },
  '淘汰': { label: '淘汰', bg: 'var(--danger-bg)', color: 'var(--danger)' },
  '待审核': { label: '待审核', bg: 'var(--warning-bg)', color: 'var(--warning)' },
  '': { label: '待审核', bg: 'var(--warning-bg)', color: 'var(--warning)' },
};

function getStatusStyle(result?: string | null) {
  return statusConfig[result || ''] || statusConfig['待审核'];
}

export function CandidateBrowser({
  candidates = [],
  selectedId,
  onSelect,
  onEdit,
  onDelete,
  onReanalyze,
  onExport,
  onResultChange,
}: CandidateBrowserProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [showMenuId, setShowMenuId] = useState<number | null>(null);
  const [editingBlock, setEditingBlock] = useState<string | null>(null);
  const [deleteConfirmId, setDeleteConfirmId] = useState<number | null>(null);
  const [localEditData, setLocalEditData] = useState<Partial<Candidate>>({});
  const [localScores, setLocalScores] = useState<ScoreDetail>({});
  const [showMobileDetail, setShowMobileDetail] = useState(false);
  const [copied, setCopied] = useState(false);

  // Ensure we have a selected candidate
  const effectiveSelectedId = selectedId ?? (candidates[0]?.id || null);

  const selectedCandidate = useMemo(
    () => candidates.find((c) => c.id === effectiveSelectedId),
    [candidates, effectiveSelectedId]
  );

  // Search + filter
  const filteredCandidates = useMemo(() => {
    return candidates.filter((c) => {
      const q = searchQuery.toLowerCase();
      const matchesSearch =
        !q ||
        (c.name || '').toLowerCase().includes(q) ||
        (c.phone || '').toLowerCase().includes(q) ||
        (c.school || '').toLowerCase().includes(q) ||
        (c.major || '').toLowerCase().includes(q);
      const matchesStatus =
        statusFilter === 'all' ||
        (statusFilter === 'pending' && !c.result) ||
        c.result === statusFilter;
      return matchesSearch && matchesStatus;
    });
  }, [candidates, searchQuery, statusFilter]);

  const statusCounts = useMemo(() => ({
    all: candidates.length,
    推荐: candidates.filter((c) => c.result === '推荐').length,
    淘汰: candidates.filter((c) => c.result === '淘汰').length,
    pending: candidates.filter((c) => !c.result).length,
  }), [candidates]);

  const handleSelect = useCallback((candidate: Candidate) => {
    onSelect?.(candidate);
    setShowMobileDetail(true);
    setShowMenuId(null);
    setEditingBlock(null);
    setDeleteConfirmId(null);
  }, [onSelect]);

  const handleStartEdit = useCallback((block: string, candidate: Candidate) => {
    setEditingBlock(block);
    setLocalEditData({ ...candidate });
    if (block === 'scores') {
      setLocalScores({ ...(candidate.score_details || {}) });
    }
  }, []);

  const handleSaveEdit = useCallback(() => {
    if (!selectedCandidate) return;
    const updated: Candidate = { ...selectedCandidate, ...localEditData };
    if (editingBlock === 'scores') {
      updated.score_details = { ...localScores };
      // Recalculate total
      let total = 0;
      Object.entries(localScores).forEach(([dim, score]) => {
        total += score;
      });
      updated.score_total = total / Object.keys(localScores).length || 0;
      updated.score_source = 'manual';
    }
    onEdit?.(updated);
    setEditingBlock(null);
    setLocalEditData({});
    setLocalScores({});
  }, [selectedCandidate, localEditData, localScores, editingBlock, onEdit]);

  const handleCancelEdit = useCallback(() => {
    setEditingBlock(null);
    setLocalEditData({});
    setLocalScores({});
  }, []);

  const handleCopy = useCallback(() => {
    if (!selectedCandidate) return;
    const text = formatCandidateForCopy(selectedCandidate);
    navigator.clipboard.writeText(text).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
  }, [selectedCandidate]);

  const handleReanalyze = useCallback(() => {
    if (selectedCandidate) {
      onReanalyze?.(selectedCandidate.id);
      setShowMenuId(null);
    }
  }, [selectedCandidate, onReanalyze]);

  const handleExport = useCallback(() => {
    if (selectedCandidate) {
      onExport?.(selectedCandidate.id);
      setShowMenuId(null);
    }
  }, [selectedCandidate, onExport]);

  const handleDelete = useCallback(() => {
    if (selectedCandidate) {
      if (deleteConfirmId === selectedCandidate.id) {
        onDelete?.(selectedCandidate.id);
        setDeleteConfirmId(null);
        setShowMenuId(null);
      } else {
        setDeleteConfirmId(selectedCandidate.id);
      }
    }
  }, [selectedCandidate, deleteConfirmId, onDelete]);

  const scoreDimensions = useMemo(() => {
    if (!selectedCandidate?.score_details) return [];
    return Object.keys(selectedCandidate.score_details);
  }, [selectedCandidate]);

  // Mobile responsive check
  const [isMobile, setIsMobile] = useState(false);

  // Check mobile on mount
  useState(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 768);
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  });

  if (candidates.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center" style={{ height: '400px', color: 'var(--text-muted)' }}>
        <Search size={48} style={{ marginBottom: 'var(--space-4)', opacity: 0.5 }} />
        <p style={{ fontSize: 'var(--text-lg)', color: 'var(--text-secondary)', marginBottom: 'var(--space-2)' }}>
          暂无候选人数据
        </p>
        <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>
          请前往「新增候选人」页面上传简历
        </p>
      </div>
    );
  }

  return (
    <div className="w-full h-full flex" style={{ backgroundColor: 'var(--bg-base)' }}>
      {/* Left Panel - Candidate List */}
      <div
        className="flex-shrink-0 flex flex-col border-r"
        style={{
          width: isMobile ? '100%' : '320px',
          backgroundColor: 'var(--bg-base)',
          borderColor: 'var(--border-subtle)',
          display: isMobile && showMobileDetail ? 'none' : 'flex',
        }}
      >
        {/* Search Bar */}
        <div
          className="p-4 border-b sticky top-0 z-10"
          style={{ borderColor: 'var(--border-subtle)', backgroundColor: 'var(--bg-base)' }}
        >
          <div
            className="flex items-center gap-2 px-3"
            style={{
              height: '36px',
              backgroundColor: 'var(--bg-input)',
              border: '1px solid var(--border-subtle)',
              borderRadius: 'var(--radius-md)',
            }}
          >
            <Search size={16} style={{ color: 'var(--text-muted)', flexShrink: 0 }} />
            <input
              type="text"
              placeholder="搜索姓名、手机、学校..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{
                flex: 1,
                backgroundColor: 'transparent',
                border: 'none',
                outline: 'none',
                color: 'var(--text-primary)',
                fontSize: 'var(--text-base)',
                minWidth: 0,
              }}
            />
          </div>
        </div>

        {/* Status Filters */}
        <div className="px-4 py-3 flex flex-col gap-1">
          {(['all', '推荐', '淘汰', 'pending'] as const).map((status) => (
            <button
              key={status}
              onClick={() => setStatusFilter(status)}
              className="flex items-center justify-between px-3 transition-colors text-left"
              style={{
                height: '32px',
                backgroundColor: statusFilter === status ? 'var(--bg-active)' : 'transparent',
                borderRadius: 'var(--radius-md)',
                border: 'none',
                cursor: 'pointer',
                color: statusFilter === status ? 'var(--text-primary)' : 'var(--text-secondary)',
                fontSize: 'var(--text-sm)',
              }}
              onMouseEnter={(e) => {
                if (statusFilter !== status) {
                  e.currentTarget.style.backgroundColor = 'var(--bg-hover)';
                }
              }}
              onMouseLeave={(e) => {
                if (statusFilter !== status) {
                  e.currentTarget.style.backgroundColor = 'transparent';
                }
              }}
            >
              <span>
                {status === 'all' && '全部'}
                {status === '推荐' && '通过'}
                {status === '淘汰' && '未通过'}
                {status === 'pending' && '待定'}
              </span>
              <span style={{ color: 'var(--text-muted)' }}>
                ({statusCounts[status]})
              </span>
            </button>
          ))}
        </div>

        <div style={{ height: '1px', backgroundColor: 'var(--border-subtle)', margin: '0 16px' }} />

        {/* Candidate List */}
        <div className="flex-1 overflow-auto">
          {filteredCandidates.length === 0 ? (
            <div className="flex flex-col items-center justify-center p-8" style={{ color: 'var(--text-muted)' }}>
              <Search size={32} style={{ marginBottom: 'var(--space-3)', opacity: 0.5 }} />
              <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-secondary)' }}>
                暂无符合条件的候选人
              </p>
            </div>
          ) : (
            filteredCandidates.map((candidate) => {
              const isSelected = candidate.id === effectiveSelectedId;
              return (
                <div
                  key={candidate.id}
                  onClick={() => handleSelect(candidate)}
                  className="relative flex items-center gap-3 px-4 cursor-pointer"
                  style={{
                    height: '72px',
                    backgroundColor: isSelected ? 'var(--bg-active)' : 'transparent',
                    borderLeft: isSelected ? '2px solid var(--accent)' : '2px solid transparent',
                  }}
                  onMouseEnter={(e) => {
                    if (!isSelected) {
                      e.currentTarget.style.backgroundColor = 'var(--bg-hover)';
                    }
                  }}
                  onMouseLeave={(e) => {
                    if (!isSelected) {
                      e.currentTarget.style.backgroundColor = 'transparent';
                    }
                  }}
                >
                  <div className="flex-1 min-w-0">
                    <div
                      className="truncate"
                      style={{
                        fontSize: 'var(--text-base)',
                        color: 'var(--text-primary)',
                        fontWeight: 'var(--font-medium)',
                      }}
                    >
                      {candidate.name || '未识别'}
                    </div>
                    <div
                      className="truncate"
                      style={{
                        fontSize: 'var(--text-sm)',
                        color: 'var(--text-muted)',
                      }}
                    >
                      {candidate.phone || '—'} · {candidate.school || '—'}
                    </div>
                  </div>
                  <div className="flex items-center gap-1 flex-shrink-0">
                    {candidate.score_total !== undefined && (
                      <>
                        <Star size={14} fill="var(--accent)" style={{ color: 'var(--accent)' }} />
                        <span
                          style={{
                            fontSize: 'var(--text-base)',
                            color: 'var(--accent)',
                            fontWeight: 'var(--font-semibold)',
                          }}
                        >
                          {candidate.score_total.toFixed(1)}
                        </span>
                      </>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* Right Panel - Candidate Detail */}
      {selectedCandidate && (
        <div
          className="flex-1 overflow-auto"
          style={{
            display: isMobile && !showMobileDetail ? 'none' : 'block',
            backgroundColor: 'var(--bg-base)',
          }}
        >
          <div className="p-6 md:p-8" style={{ maxWidth: '960px' }}>
            {/* Mobile Back Button */}
            {isMobile && (
              <button
                onClick={() => setShowMobileDetail(false)}
                className="flex items-center gap-2 mb-4"
                style={{
                  backgroundColor: 'transparent',
                  border: 'none',
                  color: 'var(--text-secondary)',
                  cursor: 'pointer',
                  fontSize: 'var(--text-sm)',
                }}
              >
                <ChevronLeft size={16} />
                返回列表
              </button>
            )}

            {/* Header */}
            <div className="flex items-start justify-between mb-6 flex-wrap gap-3">
              <div className="flex items-center gap-3 flex-wrap">
                <h2
                  style={{
                    fontSize: 'var(--text-2xl)',
                    fontWeight: 'var(--font-semibold)',
                    color: 'var(--text-primary)',
                  }}
                >
                  {selectedCandidate.name || '未知'}
                </h2>
                <div
                  className="px-2 flex items-center"
                  style={{
                    height: '20px',
                    borderRadius: 'var(--radius-sm)',
                    fontSize: 'var(--text-xs)',
                    fontWeight: 'var(--font-medium)',
                    backgroundColor: getStatusStyle(selectedCandidate.result).bg,
                    color: getStatusStyle(selectedCandidate.result).color,
                  }}
                >
                  {getStatusStyle(selectedCandidate.result).label}
                </div>
                {selectedCandidate.score_total !== undefined && (
                  <div className="flex items-center gap-1">
                    <Star size={16} fill="var(--accent)" style={{ color: 'var(--accent)' }} />
                    <span
                      style={{
                        fontSize: 'var(--text-xl)',
                        color: 'var(--accent)',
                        fontWeight: 'var(--font-semibold)',
                      }}
                    >
                      {selectedCandidate.score_total.toFixed(1)}
                    </span>
                  </div>
                )}
              </div>

              <div className="flex items-center gap-2">
                {/* Result Actions */}
                {selectedCandidate.result !== '推荐' && (
                  <button
                    onClick={() => onResultChange?.(selectedCandidate.id, '推荐')}
                    className="flex items-center justify-center gap-1 transition-all"
                    style={{
                      height: '32px',
                      padding: '0 12px',
                      backgroundColor: 'var(--success-bg)',
                      color: 'var(--success)',
                      fontSize: 'var(--text-sm)',
                      fontWeight: 'var(--font-medium)',
                      borderRadius: 'var(--radius-md)',
                      border: 'none',
                      cursor: 'pointer',
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.opacity = '0.8';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.opacity = '1';
                    }}
                  >
                    通过
                  </button>
                )}
                {selectedCandidate.result === '推荐' && (
                  <span
                    className="flex items-center gap-1 px-3"
                    style={{
                      height: '32px',
                      borderRadius: 'var(--radius-md)',
                      backgroundColor: 'var(--success-bg)',
                      color: 'var(--success)',
                      fontSize: 'var(--text-sm)',
                      fontWeight: 'var(--font-medium)',
                    }}
                  >
                    已通过
                  </span>
                )}

                {selectedCandidate.result !== '淘汰' && (
                  <button
                    onClick={() => onResultChange?.(selectedCandidate.id, '淘汰')}
                    className="flex items-center justify-center gap-1 transition-all"
                    style={{
                      height: '32px',
                      padding: '0 12px',
                      backgroundColor: 'var(--danger-bg)',
                      color: 'var(--danger)',
                      fontSize: 'var(--text-sm)',
                      fontWeight: 'var(--font-medium)',
                      borderRadius: 'var(--radius-md)',
                      border: 'none',
                      cursor: 'pointer',
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.opacity = '0.8';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.opacity = '1';
                    }}
                  >
                    淘汰
                  </button>
                )}
                {selectedCandidate.result === '淘汰' && (
                  <span
                    className="flex items-center gap-1 px-3"
                    style={{
                      height: '32px',
                      borderRadius: 'var(--radius-md)',
                      backgroundColor: 'var(--danger-bg)',
                      color: 'var(--danger)',
                      fontSize: 'var(--text-sm)',
                      fontWeight: 'var(--font-medium)',
                    }}
                  >
                    已淘汰
                  </span>
                )}

                <div style={{ width: '1px', height: '24px', backgroundColor: 'var(--border-subtle)', margin: '0 4px' }} />

                <button
                  onClick={handleCopy}
                  className="flex items-center justify-center gap-2 transition-all"
                  style={{
                    height: '36px',
                    padding: '0 16px',
                    backgroundColor: copied ? 'var(--success-bg)' : 'var(--accent)',
                    color: copied ? 'var(--success)' : 'var(--text-inverse)',
                    fontSize: 'var(--text-sm)',
                    fontWeight: 'var(--font-medium)',
                    borderRadius: 'var(--radius-md)',
                    border: 'none',
                    cursor: 'pointer',
                  }}
                >
                  {copied ? <Check size={16} /> : <Copy size={16} />}
                  {copied ? '已复制' : '复制'}
                </button>

                {/* Overflow Menu */}
                <div className="relative">
                  <button
                    onClick={() => setShowMenuId(showMenuId === selectedCandidate.id ? null : selectedCandidate.id)}
                    className="flex items-center justify-center transition-all"
                    style={{
                      width: '36px',
                      height: '36px',
                      backgroundColor: 'transparent',
                      color: 'var(--text-secondary)',
                      borderRadius: 'var(--radius-md)',
                      border: '1px solid var(--border-strong)',
                      cursor: 'pointer',
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.backgroundColor = 'var(--bg-hover)';
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.backgroundColor = 'transparent';
                    }}
                  >
                    <MoreHorizontal size={16} />
                  </button>

                  {showMenuId === selectedCandidate.id && (
                    <div
                      className="absolute right-0 mt-1 py-1 z-20"
                      style={{
                        width: '180px',
                        backgroundColor: 'var(--bg-elevated)',
                        border: '1px solid var(--border-subtle)',
                        borderRadius: 'var(--radius-lg)',
                        boxShadow: 'var(--shadow-lg)',
                      }}
                    >
                      <MenuItem icon={<Sparkles size={16} />} label="AI 重新识别" onClick={handleReanalyze} />
                      <MenuItem icon={<Pencil size={16} />} label="编辑信息" onClick={() => { setShowMenuId(null); handleStartEdit('basic', selectedCandidate); }} />
                      <MenuItem icon={<Download size={16} />} label="导出为 PDF" onClick={handleExport} />
                      <div style={{ height: '1px', backgroundColor: 'var(--border-subtle)', margin: '4px 0' }} />
                      {deleteConfirmId === selectedCandidate.id ? (
                        <>
                          <MenuItem
                            icon={<Trash2 size={16} />}
                            label="确认删除？"
                            danger
                            onClick={handleDelete}
                          />
                          <MenuItem
                            icon={<X size={16} />}
                            label="取消"
                            onClick={() => setDeleteConfirmId(null)}
                          />
                        </>
                      ) : (
                        <MenuItem
                          icon={<Trash2 size={16} />}
                          label="删除候选人"
                          danger
                          onClick={handleDelete}
                        />
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Basic Info Block */}
            <InfoBlock
              title="基本信息"
              isEditing={editingBlock === 'basic'}
              onEdit={() => handleStartEdit('basic', selectedCandidate)}
              onCancel={handleCancelEdit}
              onSave={handleSaveEdit}
            >
              {editingBlock === 'basic' ? (
                <>
                  <EditRow label="姓名" value={localEditData.name || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, name: v }))} />
                  <EditRow label="手机号" value={localEditData.phone || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, phone: v }))} />
                  <EditRow label="邮箱" value={localEditData.email || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, email: v }))} />
                  <EditRow label="性别" value={localEditData.gender || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, gender: v }))} />
                  <EditRow label="出生年份" value={String(localEditData.birth_year || '')} onChange={(v) => setLocalEditData((d) => ({ ...d, birth_year: v ? parseInt(v) : null }))} />
                  <EditRow label="学校" value={localEditData.school || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, school: v }))} />
                  <EditRow label="专业" value={localEditData.major || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, major: v }))} />
                  <EditRow label="学历" value={localEditData.education || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, education: v }))} />
                  <EditRow label="是否应届" value={localEditData.is_fresh_grad || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, is_fresh_grad: v }))} />
                  <EditRow label="招聘渠道" value={localEditData.channel || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, channel: v }))} />
                  <EditRow label="实习生" value={localEditData.intern_name || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, intern_name: v }))} />
                  <EditRow label="沟通时间" value={localEditData.communicate_time || ''} onChange={(v) => setLocalEditData((d) => ({ ...d, communicate_time: v }))} />
                </>
              ) : (
                <>
                  <InfoRow label="姓名" value={selectedCandidate.name || '—'} />
                  <InfoRow label="手机号" value={selectedCandidate.phone || '—'} />
                  <InfoRow label="邮箱" value={selectedCandidate.email || '—'} />
                  <InfoRow label="性别" value={selectedCandidate.gender || '—'} />
                  <InfoRow label="出生年份" value={selectedCandidate.birth_year ? String(selectedCandidate.birth_year) : '—'} />
                  <InfoRow label="学校" value={selectedCandidate.school || '—'} />
                  <InfoRow label="专业" value={selectedCandidate.major || '—'} />
                  <InfoRow label="学历" value={selectedCandidate.education || '—'} />
                  <InfoRow label="是否应届" value={selectedCandidate.is_fresh_grad || '—'} />
                  <InfoRow label="招聘渠道" value={selectedCandidate.channel || '—'} />
                  <InfoRow label="实习生" value={selectedCandidate.intern_name || '—'} />
                  <InfoRow label="沟通时间" value={selectedCandidate.communicate_time || '—'} />
                </>
              )}
            </InfoBlock>

            {/* Description Block */}
            {selectedCandidate.description && (
              <InfoBlock title="台账内容" isEditing={false}>
                <div
                  style={{
                    padding: 'var(--space-4)',
                    backgroundColor: 'var(--bg-base)',
                    borderRadius: 'var(--radius-md)',
                    fontSize: 'var(--text-base)',
                    color: 'var(--text-primary)',
                    lineHeight: 'var(--leading-relaxed)',
                    whiteSpace: 'pre-wrap',
                  }}
                >
                  {selectedCandidate.description}
                </div>
              </InfoBlock>
            )}

            {/* Remarks Block */}
            {selectedCandidate.remarks && (
              <InfoBlock title="备注" isEditing={false}>
                <div
                  style={{
                    padding: 'var(--space-4)',
                    backgroundColor: 'var(--bg-base)',
                    borderRadius: 'var(--radius-md)',
                    fontSize: 'var(--text-base)',
                    color: 'var(--text-primary)',
                    lineHeight: 'var(--leading-relaxed)',
                    whiteSpace: 'pre-wrap',
                  }}
                >
                  {selectedCandidate.remarks}
                </div>
              </InfoBlock>
            )}

            {/* Ability Scores Block */}
            {selectedCandidate.score_details && Object.keys(selectedCandidate.score_details).length > 0 && (
              <InfoBlock
                title="能力评分"
                isEditing={editingBlock === 'scores'}
                onEdit={() => handleStartEdit('scores', selectedCandidate)}
                onCancel={handleCancelEdit}
                onSave={handleSaveEdit}
              >
                {editingBlock === 'scores' ? (
                  <>
                    {scoreDimensions.map((dim) => (
                      <div key={dim} className="flex items-center gap-4 py-2">
                        <span
                          className="w-24 flex-shrink-0"
                          style={{
                            fontSize: 'var(--text-base)',
                            color: 'var(--text-secondary)',
                          }}
                        >
                          {dim}
                        </span>
                        <input
                          type="range"
                          min={1}
                          max={5}
                          step={0.5}
                          value={localScores[dim] || 0}
                          onChange={(e) =>
                            setLocalScores((s) => ({ ...s, [dim]: parseFloat(e.target.value) }))
                          }
                          style={{ flex: 1, accentColor: 'var(--accent)' }}
                        />
                        <span
                          className="w-12 text-right"
                          style={{
                            fontSize: 'var(--text-base)',
                            color: 'var(--accent)',
                            fontWeight: 'var(--font-semibold)',
                          }}
                        >
                          {(localScores[dim] || 0).toFixed(1)}
                        </span>
                      </div>
                    ))}
                    <div
                      className="mt-3 pt-3"
                      style={{
                        borderTop: '1px solid var(--border-subtle)',
                        fontSize: 'var(--text-base)',
                        color: 'var(--text-secondary)',
                      }}
                    >
                      加权总分:{' '}
                      <span style={{ color: 'var(--accent)', fontWeight: 'var(--font-semibold)' }}>
                        {(
                          Object.values(localScores).reduce((a, b) => a + b, 0) /
                          Math.max(Object.keys(localScores).length, 1)
                        ).toFixed(2)}
                      </span>{' '}
                      / 5.0
                    </div>
                  </>
                ) : (
                  <>
                    {scoreDimensions.map((dim) => {
                      const score = selectedCandidate.score_details?.[dim] || 0;
                      const pct = (score / 5) * 100;
                      return (
                        <div key={dim} className="flex items-center gap-4 py-2">
                          <span
                            className="w-24 flex-shrink-0"
                            style={{
                              fontSize: 'var(--text-base)',
                              color: 'var(--text-secondary)',
                            }}
                          >
                            {dim}
                          </span>
                          <div className="flex-1 relative">
                            <div
                              style={{
                                height: '6px',
                                backgroundColor: 'var(--bg-hover)',
                                borderRadius: 'var(--radius-full)',
                                overflow: 'hidden',
                              }}
                            >
                              <div
                                style={{
                                  width: `${pct}%`,
                                  height: '100%',
                                  backgroundColor: 'var(--accent)',
                                  transition: 'width 300ms var(--ease-out)',
                                }}
                              />
                            </div>
                          </div>
                          <span
                            className="w-12 text-right"
                            style={{
                              fontSize: 'var(--text-base)',
                              color: 'var(--accent)',
                              fontWeight: 'var(--font-semibold)',
                            }}
                          >
                            {score.toFixed(1)}
                          </span>
                        </div>
                      );
                    })}
                  </>
                )}
              </InfoBlock>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

/* ========== Helper Components ========== */

function InfoBlock({
  title,
  children,
  isEditing,
  onEdit,
  onCancel,
  onSave,
}: {
  title: string;
  children: React.ReactNode;
  isEditing: boolean;
  onEdit?: () => void;
  onCancel?: () => void;
  onSave?: () => void;
}) {
  return (
    <div
      className="mb-6"
      style={{
        backgroundColor: 'var(--bg-surface)',
        border: '1px solid var(--border-subtle)',
        borderRadius: 'var(--radius-lg)',
        overflow: 'hidden',
      }}
    >
      {/* Block Header */}
      <div
        className="flex items-center justify-between px-6"
        style={{
          height: '44px',
          borderBottom: '1px solid var(--border-subtle)',
        }}
      >
        <h3
          style={{
            fontSize: 'var(--text-base)',
            fontWeight: 'var(--font-medium)',
            color: 'var(--text-secondary)',
            textTransform: 'uppercase',
            letterSpacing: '0.5px',
          }}
        >
          {title}
        </h3>
        {onEdit && !isEditing && (
          <button
            onClick={onEdit}
            className="flex items-center justify-center transition-colors"
            style={{
              width: '32px',
              height: '32px',
              backgroundColor: 'transparent',
              color: 'var(--text-secondary)',
              borderRadius: 'var(--radius-md)',
              border: 'none',
              cursor: 'pointer',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = 'var(--bg-hover)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent';
            }}
          >
            <Pencil size={16} />
          </button>
        )}
      </div>

      {/* Block Content */}
      <div className="p-6">{children}</div>

      {/* Edit Actions */}
      {isEditing && onCancel && onSave && (
        <div className="flex items-center justify-end gap-3 px-6 pb-6">
          <button
            onClick={onCancel}
            style={{
              height: '32px',
              padding: '0 12px',
              backgroundColor: 'transparent',
              color: 'var(--text-secondary)',
              fontSize: 'var(--text-sm)',
              fontWeight: 'var(--font-medium)',
              border: 'none',
              cursor: 'pointer',
            }}
          >
            取消
          </button>
          <button
            onClick={onSave}
            className="flex items-center gap-2 transition-all"
            style={{
              height: '32px',
              padding: '0 12px',
              backgroundColor: 'var(--accent)',
              color: 'var(--text-inverse)',
              fontSize: 'var(--text-sm)',
              fontWeight: 'var(--font-medium)',
              borderRadius: 'var(--radius-md)',
              border: 'none',
              cursor: 'pointer',
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = 'var(--accent-hover)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'var(--accent)';
            }}
          >
            <Check size={16} />
            保存
          </button>
        </div>
      )}
    </div>
  );
}

function InfoRow({ label, value }: { label: string; value: string }) {
  return (
    <div
      className="flex items-center py-2"
      style={{ borderBottom: '1px solid var(--border-subtle)' }}
    >
      <span
        className="flex-shrink-0"
        style={{
          width: '100px',
          fontSize: 'var(--text-sm)',
          color: 'var(--text-muted)',
        }}
      >
        {label}
      </span>
      <span
        style={{
          fontSize: 'var(--text-base)',
          color: 'var(--text-primary)',
          wordBreak: 'break-all',
        }}
      >
        {value}
      </span>
    </div>
  );
}

function EditRow({
  label,
  value,
  onChange,
}: {
  label: string;
  value: string;
  onChange: (value: string) => void;
}) {
  return (
    <div
      className="flex items-center py-2"
      style={{ borderBottom: '1px solid var(--border-subtle)' }}
    >
      <span
        className="flex-shrink-0"
        style={{
          width: '100px',
          fontSize: 'var(--text-sm)',
          color: 'var(--text-muted)',
        }}
      >
        {label}
      </span>
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        style={{
          flex: 1,
          minWidth: 0,
          height: '32px',
          padding: '0 8px',
          backgroundColor: 'var(--bg-input)',
          border: '1px solid var(--border-subtle)',
          borderRadius: 'var(--radius-sm)',
          color: 'var(--text-primary)',
          fontSize: 'var(--text-base)',
          outline: 'none',
        }}
        onFocus={(e) => {
          e.currentTarget.style.borderColor = 'var(--border-focus)';
        }}
        onBlur={(e) => {
          e.currentTarget.style.borderColor = 'var(--border-subtle)';
        }}
      />
    </div>
  );
}

function MenuItem({
  icon,
  label,
  danger,
  onClick,
}: {
  icon: React.ReactNode;
  label: string;
  danger?: boolean;
  onClick: () => void;
}) {
  return (
    <button
      className="w-full flex items-center gap-2 px-3 transition-colors text-left"
      style={{
        height: '36px',
        backgroundColor: 'transparent',
        color: danger ? 'var(--danger)' : 'var(--text-primary)',
        fontSize: 'var(--text-base)',
        border: 'none',
        cursor: 'pointer',
      }}
      onMouseEnter={(e) => {
        e.currentTarget.style.backgroundColor = danger ? 'var(--danger-bg)' : 'var(--bg-hover)';
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.backgroundColor = 'transparent';
      }}
      onClick={onClick}
    >
      {icon}
      {label}
    </button>
  );
}

function formatCandidateForCopy(candidate: Candidate): string {
  const lines = [
    `姓名: ${candidate.name || '—'}`,
    `手机: ${candidate.phone || '—'}`,
    `邮箱: ${candidate.email || '—'}`,
    `学校: ${candidate.school || '—'}`,
    `专业: ${candidate.major || '—'}`,
    `学历: ${candidate.education || '—'}`,
    `性别: ${candidate.gender || '—'}`,
    `出生年份: ${candidate.birth_year || '—'}`,
    `是否应届: ${candidate.is_fresh_grad || '—'}`,
    `招聘渠道: ${candidate.channel || '—'}`,
    `沟通时间: ${candidate.communicate_time || '—'}`,
    `结果: ${candidate.result || '待审核'}`,
    '',
    `评分: ${candidate.score_total?.toFixed(2) || '—'}`,
  ];
  if (candidate.score_details) {
    lines.push('详细评分:');
    Object.entries(candidate.score_details).forEach(([dim, score]) => {
      lines.push(`  ${dim}: ${score}`);
    });
  }
  return lines.join('\n');
}
